// Utility functions
function xy(x, y) {
  return `${x},${y}`;
}

function c(v) {
  let temp = `000000${v.toString(16)}`;
  temp = temp.substring(temp.length - 6);
  return `#${temp}`;
}

function fit(c) {
  return Math.min(255, Math.max(0, Math.floor(c)));
}

function blend(a1, a2, weight = 0.33) {
  let r1 = (a1 >> 16) & 0xff;
  let g1 = (a1 >> 8) & 0xff;
  let b1 = a1 & 0xff;

  let r2 = (a2 >> 16) & 0xff;
  let g2 = (a2 >> 8) & 0xff;
  let b2 = a2 & 0xff;

  let r = fit(r1 * weight + r2 * (1 - weight));
  let g = fit(g1 * weight + g2 * (1 - weight));
  let b = fit(b1 * weight + b2 * (1 - weight));

  return (r << 16) | (g << 8) | b;
}

// Columns class
class Columns {
  constructor(width, height) {
    this.columns = {};
    this.nodes = {};
    this.widths = [];
    this.heights = [];
    this.width = width;
    this.height = height;
    this.gapY = 0.4;
    this.colWeights = {};
    this.colSpaceWeights = {};
    this.columnCount = 0;
  }

  add(node) {
    let col = node.column;
    this.columnCount = Math.max(col + 1, this.columnCount);
    if (!(col in this.columns)) {
      this.columns[col] = [];
    }
    let row = this.columns[col].length;
    this.columns[col].push(node);
    node.row = row;
    this.nodes[xy(node.column, node.row)] = node;
  }

  calculate() {
    let columnSpan = 0;
    for (let i = 0; i < this.columnCount; ++i) {
      if (i != 0) {
        if (this.colSpaceWeights[i - 1]) {
          columnSpan += this.colSpaceWeights[i - 1];
        } else {
          columnSpan += 0.4;
        }
      }
      if (this.colWeights[i]) {
        columnSpan += this.colWeights[i];
      } else {
        columnSpan += 1;
      }
    }

    let widthPerWeight = this.width / columnSpan;
    let widthOffset = 0;
    let columnX = [];
    let columnWidth = [];

    for (let i = 0; i < this.columnCount; ++i) {
      if (i != 0) {
        let gapX = 0.4;
        if (this.colSpaceWeights[i - 1]) {
          gapX = this.colSpaceWeights[i - 1];
        }
        widthOffset += gapX * widthPerWeight;
      }
      columnX.push(widthOffset);
      let width;
      if (this.colWeights[i]) {
        width = this.colWeights[i] * widthPerWeight;
      } else {
        width = widthPerWeight;
      }
      columnWidth.push(width);

      let rowSpan =
        this.columns[i].length + (this.columns[i].length - 1) * this.gapY;
      let rowHeightPerWeight = this.height / rowSpan;
      let rowOffset = 0;

      for (let j = 0; j < this.columns[i].length; ++j) {
        this.columns[i][j].setRect({
          x: widthOffset,
          y: rowOffset,
          width: width,
          height: rowHeightPerWeight,
        });
        rowOffset += rowHeightPerWeight;
        rowOffset += this.gapY * rowHeightPerWeight;
      }

      widthOffset += width;
    }
  }
}

// Initialize columns
const columns = new Columns(1920 / 1.5, 1080 / 1.5);

// Node class
class Node {
  #rect = { x: 10, y: 10, width: 20, height: 20 };
  constructor(name, column, color, exists, trimLeft = 0, trimRight = 0) {
    if (exists === undefined) {
      exists = true;
    }
    this.trimLeft = trimLeft;
    this.trimRight = trimRight;
    this.exists = exists;
    this.name = name;
    this.column = column;
    this.color = Math.random * 0xffffff;
    this.height = 3;
    this.row = -1;
    this.outgoing = [];
    this.outgoingExists = [];
    this.outgoingNames = [];
    this.incoming = [];
    if (color) {
      this.color = color;
    } else {
      this.color = 0x008f00;
    }
    columns.add(this);
    nodes[name] = this;
  }

  connect(other, exists = true, name = "") {
    this.outgoing.push(other);
    this.outgoingExists.push(exists);
    this.outgoingNames.push(name);
    other.incoming.push(this);
  }

  setRect(rect) {
    this.#rect = rect;
    if (this.trimLeft != 0) {
      this.#rect.x += this.trimLeft;
    }
    if (this.trimRight != 0) {
      this.#rect.width -= this.trimRight;
    }
  }

  rect() {
    return this.#rect;
  }

  getGradients(output) {
    for (let i = 0; i < this.outgoing.length; ++i) {
      let node = this.outgoing[i];
      let exists = this.outgoingExists[i] && this.exists;
      let from = exists ? this.color : darker(this.color, false);
      let to = exists ? node.color : darker(node.color, false);
      let name = `c_${from}_${to}`;

      // Create gradient element
      const gradient = document.createElementNS(
        "http://www.w3.org/2000/svg",
        "linearGradient"
      );
      gradient.setAttribute("id", name);

      const stop1 = document.createElementNS(
        "http://www.w3.org/2000/svg",
        "stop"
      );
      stop1.setAttribute("style", `stop-color: ${c(from)}`);
      stop1.setAttribute("offset", "0%");

      const stop2 = document.createElementNS(
        "http://www.w3.org/2000/svg",
        "stop"
      );
      stop2.setAttribute("style", `stop-color: ${c(to)}`);
      stop2.setAttribute("offset", "100%");

      gradient.appendChild(stop1);
      gradient.appendChild(stop2);

      output[name] = gradient;
    }
  }

  connectedIncoming(name) {
    if (this.name === name) {
      return true;
    }
    return this.incoming.some((item) => item.connectedIncoming(name));
  }

  connected(name) {
    if (this.name === name) {
      return true;
    }
    return this.connectedIncoming(name) || this.connectedOutgoing(name);
  }

  connectedOutgoing(name) {
    if (this.name === name) {
      return true;
    }
    return this.outgoing.some((item) => item.connectedOutgoing(name));
  }

  render(connectedTo, onClick) {
    if (connectedTo != "") {
      if (connectedTo === this.name) {
        // good
      } else if (
        this.connectedIncoming(connectedTo) ||
        this.connectedOutgoing(connectedTo)
      ) {
        // good
      } else {
        return { lines: [], labels: [], body: [] };
      }
    }
    let { x, y, width, height } = this.rect();

    let lines = [];
    let labels = [];

    if (this.outgoing.length > 0) {
      let outgoingHeight = height / this.outgoing.length;
      for (let i = 0; i < this.outgoing.length; ++i) {
        let exists = this.outgoingExists[i] && this.exists;
        let target = this.outgoing[i];
        let name = this.outgoingNames[i];
        let fromColor = exists ? this.color : darker(this.color, false);
        let toColor = exists ? target.color : darker(target.color, false);
        let targetRect = target.rect();
        let targetHeight = targetRect.height / target.incoming.length;
        let index = target.incoming.indexOf(this);

        let gradientName = `c_${fromColor}_${toColor}`;

        let points = [];
        points.push({ x: x + width, y: y + i * outgoingHeight });
        points.push({
          x: targetRect.x,
          y: targetRect.y + targetHeight * index,
        });
        points.push({
          x: targetRect.x,
          y: targetRect.y + targetHeight * (index + 1),
        });
        points.push({ x: x + width, y: y + (i + 1) * outgoingHeight });
        let overScan = 5;
        let p = (index, xOffset) =>
          `${points[index].x + xOffset} ${points[index].y}`;
        let qMult = 1;
        if (targetRect.x <= x + width) {
          qMult = -1;
        }
        let q = (index, x) =>
          `${points[index].x + x * qMult} ${points[index].y}`;

        let d = `M ${p(0, -overScan)} C ${q(0, 80)}, ${q(1, -80)}, ${p(1, 5)} 
        L ${p(2, 5)}
        C ${q(2, -80)}, ${q(3, 80)}, ${p(3, -5)}
        Z`;

        let average = { x: 0, y: 0 };
        for (let p of points) {
          average.x += p.x;
          average.y += p.y;
        }
        average.x /= points.length;
        average.y /= points.length;

        if (connectedTo == "" || target.connected(connectedTo)) {
          // Create path element
          const path = document.createElementNS(
            "http://www.w3.org/2000/svg",
            "path"
          );
          path.setAttribute(
            "style",
            `opacity: 55%; fill: url(#${gradientName})`
          );
          path.setAttribute("d", d);
          lines.push(path);

          if (connectedTo != "" && name != "") {
            // Create text element
            const text = document.createElementNS(
              "http://www.w3.org/2000/svg",
              "text"
            );
            text.setAttribute("x", average.x);
            text.setAttribute("y", average.y);
            text.setAttribute("width", 50);
            text.setAttribute("height", 50);
            text.setAttribute(
              "style",
              `fill: ${c(blend(this.color, 0xffffff))}; font-size: 0.8em;`
            );
            text.setAttribute("text-anchor", "middle");
            text.setAttribute("dominant-baseline", "middle");
            text.addEventListener("click", onClick);
            text.textContent = name + (exists ? "" : "*");
            labels.push(text);
          }
        }
      }
    }

    // Create rect element
    const rect = document.createElementNS("http://www.w3.org/2000/svg", "rect");
    rect.setAttribute("x", x);
    rect.setAttribute("y", y);
    rect.setAttribute("rx", 10);
    rect.setAttribute("ry", 10);
    rect.setAttribute("width", width);
    rect.setAttribute("height", height);
    rect.setAttribute(
      "style",
      `fill: ${c(this.exists ? this.color : darker(this.color, false))}`
    );
    rect.addEventListener("click", onClick);

    // Create text element
    const text = document.createElementNS("http://www.w3.org/2000/svg", "text");
    text.setAttribute("x", x + width / 2);
    text.setAttribute("y", y + height / 2);
    text.setAttribute("width", width);
    text.setAttribute("height", height);
    text.setAttribute(
      "style",
      `fill: ${c(this.exists ? 0xffffff : darker(0xffffff, false))}`
    );
    text.setAttribute("text-anchor", "middle");
    text.setAttribute("dominant-baseline", "middle");
    text.addEventListener("click", onClick);
    text.textContent = this.name + (this.exists ? "" : "*");

    return {
      lines,
      labels,
      body: [rect, text],
    };
  }
}

