function darker(vale, exists = true) {
  let r = (vale >> 16) & 0xff;
  let g = (vale >> 8) & 0xff;
  let b = vale & 0xff;
  let factor = exists ? 0.6 : 0.3;
  r = Math.floor(r * factor);
  g = Math.floor(g * factor);
  b = Math.floor(b * factor);
  return (r << 16) | (g << 8) | b;
}

function lighter(vale) {
  let r = (vale >> 16) & 0xff;
  let g = (vale >> 8) & 0xff;
  let b = vale & 0xff;
  let factor = 1.8;
  r = Math.min(255, Math.floor(r * factor));
  g = Math.min(255, Math.floor(g * factor));
  b = Math.min(255, Math.floor(b * factor));
  return (r << 16) | (g << 8) | b;
}

