// Main application
let connectedTo = "";

function toggleShow(nodeName) {
  if (connectedTo != "") {
    connectedTo = "";
  } else {
    connectedTo = nodeName;
  }
  render();
}

function render() {
  const svg = document.getElementById("diagram");
  const gradientsContainer = document.getElementById("gradients");

  // Clear existing content but keep the gradients container
  const existingGradients = gradientsContainer.innerHTML;
  svg.innerHTML = `<defs id="gradients"></defs>`;
  const newGradientsContainer = document.getElementById("gradients");

  // Create gradients
  let gradients = {};
  Object.keys(nodes).forEach((n) => nodes[n].getGradients(gradients));
  Object.keys(gradients).forEach((id) => {
    newGradientsContainer.appendChild(gradients[id]);
  });

  let allLines = [];
  let allLabels = [];
  let allBody = [];

  Object.keys(nodes).forEach((n) => {
    let { lines, labels, body } = nodes[n].render(connectedTo, (e) => {
      e.stopPropagation();
      toggleShow(n);
    });
    allLines.push(...lines);
    allLabels.push(...labels);
    allBody.push(...body);
  });

  // Add elements to SVG
  allLines.forEach((line) => svg.appendChild(line));
  allBody.forEach((body) => svg.appendChild(body));
  allLabels.forEach((label) => svg.appendChild(label));
}

// Initialize the application
document.addEventListener("DOMContentLoaded", function () {
  const container = document.getElementById("ds_container");

  container.addEventListener("click", function (e) {
    e.stopPropagation();
    toggleShow("");
  });

  // Add click handler to SVG as well
  const svg = document.getElementById("diagram");
  svg.addEventListener("click", function (e) {
    e.stopPropagation();
    toggleShow("");
  });

  render();
});
